  "provider": {
    "trustfork-minimax": {
      "models": {
        "MiniMax-M3": {},
        "MiniMax-M2.5": {}
      },
      "npm": "@ai-sdk/openai-compatible",
      "name": "MiniMax",
      "options": {
        "baseURL": "https://api.minimaxi.com/v1",
        "apiKey": "{env:MINIMAX_API_KEY}"
      }
    }
  },
  "agent": {
    "orchestrator": {
      "description": "Coordinates the configured subagents for the task.",
      "mode": "primary",
      "tools": {
        "*": false,
        "bash": false,
        "edit": false,
        "write": false,
        "read": false,
        "grep": false,
        "glob": false,
        "list": false,
        "webfetch": false,
        "todowrite": false,
        "todoread": false,
        "patch": false,
        "skill": false,
        "question": false,
        "task": true
      },
      "permission": {
        "task": {
          "*": "deny",
          "candidate_a": "allow",
          "candidate_b": "allow",
          "candidate_c": "allow",
          "candidate_d": "allow"
        }
      }
    },
    "candidate_a": {
      "description": "Subagent A.",
